    "pooled_p99": {
      "supported_as_descriptive_only": "A pooled p99 of the observed 200 requests can be described as a pooled-sample percentile if the percentile definition, population, and window are stated.",
      "not_supported": "It is not 200 independent service repetitions. Requests within a process run are correlated, the two runs yield at most two run-level units, and all baseline runs before all changed runs confound condition with time, drift, warmup, cache, and environment. Pooled p99 does not provide independent evidence of a changed distribution or a causal effect."
    },
    "zero_violation_bernoulli": {
      "n_trials": 200,
      "alpha_one_sided": 0.05,
      "upper_bound": 0.014867039,
      "upper_bound_percent": 1.4867039,
      "supports_below_1_percent": false,
      "explanation": "Under the separate stipulated iid fixed-sample Bernoulli model, zero violations in 200 trials gives q_U = 1 - 0.05^(1/200) = about 1.4867%, so a below-1% claim is not supported at 95% one-sided confidence. A zero-violation single final look strictly below 1% requires more than log(0.05)/log(0.99) ~= 298.07, hence at least 299 independent iid trials.",
      "correlated_runs": "Two correlated service runs do not inherit the iid Bernoulli model. The 200 requests are clustered within runs and are not 200 independent trials; run, order, warmup, cache, and load history induce correlation. A zero-violation bound cannot be transferred to the two-run service setting without an explicit independent-unit and hierarchical model."
    }
  },
  "experiment_plan": {
    "two_run_p99_redesign": {
      "unit": "independent complete service/process run or randomized time block; requests within a run are correlated outcomes.",
      "assignment": "Predefine multiple blocks and randomize or balance baseline and changed order within each block, for example ABBA or a randomized complete block ordering; do not run all baseline before all changed.",
      "repetitions": "Use a pilot to characterize run-level variance and tail-event frequency, then predefine the number of independent runs and requests per run. Do not treat pooled requests as independent repetitions.",
